// The frontier's shapes (T-291; C-075): what buildFrontier reads, what each source is given and offers, and the ports
// it reads stored state and the bundle through. The contract types are imported as types only (ADR-005: generated by
// `npm run contracts:types`, never committed), so nothing here loads the generated modules at run time.
//
//   - K-09 v1 buildFrontier (contracts/tool-api): the request and the answer;
//   - K-02 v1 context (contracts/model): the choices, open questions, cards and targets the frontier gives decide;
//   - K-05 v1.2 readTurnState (contracts/data-access): the turn's stored state as one read of the primary sees it,
//     open questions in K-04 v1's shape (step, options as sent, versions read, bundle id) among it. T-219 serves the
//     real read; the frontier reaches it only through the repo port below, joined at D-017.

import type * as K05 from "../../../../contracts/generated/data-access/data-access.v1.2";
import type * as K02 from "../../../../contracts/generated/model/model.v1";
import type { AnswerOf, RequestOf } from "../../tool-api/calls";

export type BuildFrontierRequest = RequestOf<"buildFrontier">;
export type BuildFrontierAnswer = AnswerOf<"buildFrontier">;

export type Context = K02.Context;
export type Choice = K02.Choice;
export type OpenQuestion = K02.OpenQuestion;
export type StepCard = K02.StepCard;
export type Target = K02.Target;
export type Time = K02.Time;
export type StakesReason = K02.StakesReason;
export type AnswerField = K02.AnswerField;
export type Person = K02.Person;

/** A flow (K-01 v1 flowLetter): A, the customer comes to the business; B, the business goes to the customer. */
export type FlowLetter = "A" | "B";

/** A bundle id (CQ-09): the content hash and the build number. */
export interface BundleId {
  hash: string;
  build: number;
}

/** K-05 v1.2 readTurnState: the request, its answer, and its errors (notFound, unknownFact, transient). */
export type ReadTurnStateRequest = K05.ReadTurnStateRequest;
export type TurnState = K05.ReadTurnStateResponse;
export type ReadTurnStateErrors = K05.ReadTurnStateErrors;
export type ReadTurnStateAnswer = TurnState | ReadTurnStateErrors;
/** One live open question sent to the handle (K-04 v1 open_questions, as K-05 v1.2 reads it). */
export type OpenQuestionRow = TurnState["openQuestions"][number];

/** K-05 v1 transientError: the database could not answer now; nothing was read, and the same read may be sent again. */
export interface TransientError {
  error: "transient";
  sqlstate: string;
}

/**
 * The visit times of bookings: each booking's booked time (K-04 v1 reservations.during, its start) in the visit's zone
 * (S13-03). No frozen K-05 call reads it yet (K-05 v1.2 open gap 25); until one does, the adapter answers a booking it
 * cannot read with `visitAt` null, and the frontier offers none of that booking's options (fail closed).
 */
export interface VisitTimesRequest {
  bookingIds: string[];
}

export type VisitTimesAnswer =
  { result: "visits"; visits: { bookingId: string; visitAt: Time | null }[] } | TransientError;

/**
 * What the frontier reads from stored state, through the repo the Tool API base gives its handler: one transaction under
 * the call's business (row-level security, arch 10 line 546), on the primary, uncached (arch 02 line 117). Each read is
 * the action layer's (arch 02 line 139); the database engineer's adapter joins at D-017.
 */
export interface FrontierRepo {
  /** K-05 v1.2 readTurnState (T-219). */
  readTurnState(request: ReadTurnStateRequest): Promise<ReadTurnStateAnswer>;
  /** The open questions' bookings' visit times (K-05 v1.2 open gap 25). */
  readVisitTimes(request: VisitTimesRequest): Promise<VisitTimesAnswer>;
}

/**
 * The bundles the frontier reads steps, branches and cards from (K-01 v1): the turn's pinned bundle, and the bundle each
 * open question was asked under. Each value is read under its bundle id from KV, or PostgreSQL's copy on a miss (arch 10
 * line 536), and handed over parsed; the frontier checks the fields it reads itself.
 */
export interface FrontierBundles {
  /** K-01 v1 `manifest` of the bundle, or null when neither KV nor PostgreSQL's copy holds it. */
  manifest(bundleId: BundleId): Promise<unknown>;
  /** K-01 v1 `flowGraph` of one flow of the bundle, or null when the bundle holds no such flow. */
  flow(bundleId: BundleId, flow: FlowLetter): Promise<unknown>;
}

// ---------------------------------------------------------------------------------------------------------------
// The bundle, as the frontier reads it (bundle.ts narrows K-01's values to these)

/** K-01 v1 `effect`, the fields the frontier reads: its kind and its ref (a gives key, record field or amount). */
export interface BundleEffect {
  kind: string;
  ref: string | null;
}

/** K-01 v1 `branch`, the fields the frontier reads. */
export interface BundleBranch {
  label: string;
  /** message, lookup or clock (arch 03 line 161). */
  tag: string;
  steps: string[];
  /** end, merge or left out (read as merge: K-01 README "A branch with no end merges"). */
  end: string | null;
  rejoinAt: string | null;
  answerFields: AnswerField[];
  effects: BundleEffect[];
}

/**
 * What a split is to the stakes walk, from its branches' tags (K-01 v1 branch.tag; arch 03 lines 161 and 191):
 *   - asks: a message or a clock branch, so the split asks someone or waits; the walk stops there;
 *   - code: every branch a lookup, so code settles it and nobody is asked; the walk counts it and goes down every branch;
 *   - unknown: a split the walk cannot classify (bundle.ts splitOf), the safer route.
 */
export type SplitKind = "asks" | "code" | "unknown";

/** K-01 v1 `step`, the fields the frontier reads. */
export interface BundleStep {
  id: string;
  /** For a split (SPEC-master 4 'type'), what it is to the stakes walk; null for a plain step. */
  split: SplitKind | null;
  gives: string[];
  next: string | null;
  branches: BundleBranch[];
  effects: BundleEffect[];
  /** The step card as the bundle holds it (K-01 v1 `card`, which K-02 v1's stepCard reuses), or null. */
  card: StepCard["card"] | null;
}

/** A split's branch whose own steps list a step (K-01 v1 branch.steps). */
export interface Enclosing {
  readonly split: BundleStep;
  readonly branch: BundleBranch;
}

/** One flow graph of a bundle. */
export interface FlowView {
  readonly flow: FlowLetter;
  step(id: string): BundleStep | null;
  /**
   * The branches whose own steps list this step: one for a step on a branch's list, none for a step on its section's
   * main path (or whose split this graph does not hold). Where a list ends (K-01 v1 step.next null), that branch decides
   * where the walk goes (its end, or its rejoinAt).
   */
  enclosing(id: string): readonly Enclosing[];
  /** The always-on rules' prefix hash (K-01 v1 routingTables.alwaysOn.prefixSha256), or null when the graph has none. */
  readonly alwaysOnSha256: string | null;
  /**
   * The graph's routing tables as parsed (K-01 v1 routingTables: hubs, doors, the any-time rows, the homes), for the
   * sources that read them (hubs and doors, T-293; any-time rows, T-294), each narrowing the fields it reads.
   */
  readonly routing: Readonly<Record<string, unknown>>;
}

/** A bundle read for one call: its id, whether it is partial (K-01 v1 manifest.partial), and the flows it holds. */
export interface BundleView {
  readonly bundleId: BundleId;
  /** A partial bundle holds a few steps: a step it does not hold is not reachable (K-01 README, fixtures). */
  readonly partial: boolean;
  readonly flows: Partial<Record<FlowLetter, FlowView>>;
}

// ---------------------------------------------------------------------------------------------------------------
// Sources

/** A choice as a source offers it: everything but its id, which the assembler gives in frontier order. */
export type DraftChoice = Omit<Choice, "choiceId">;

/** What one source adds to the frontier: choices, and the open questions and full step cards they come with. */
export interface SourceOffer {
  openQuestions: OpenQuestion[];
  choices: DraftChoice[];
  cards: StepCard[];
}

/** The labels a source may write in the frontier's log: ids and codes, never a value's words (K-08 labels). */
export interface LogFields {
  source?: string;
  error?: string;
  problems?: number;
  open_question_id?: string;
  step?: string;
  booking_id?: string;
}

/** The frontier's log for one call (log.ts): each line names its event, the trace and the turn, and labels only. */
export interface FrontierLogger {
  warn(event: FrontierEvent, fields?: LogFields): void;
}

/** What the frontier logs. Every line is a label: never a choice's words, a text, a name or a number. */
export type FrontierEvent =
  /** A source slot whose module is not built yet: it offers nothing. */
  | "frontier_source_missing"
  /** A source that threw or rejected: it offers nothing. */
  | "frontier_source_failed"
  /** A source whose offer K-02 v1 refuses: it offers nothing. */
  | "frontier_source_refused"
  /** An open question the guard listed that this business's read does not hold (another business's, or closed). */
  | "frontier_question_unread"
  /** An open question with no part gone yet (K-05 v1.2 sentAt null): not sent, so not offered. */
  | "frontier_question_not_sent"
  /** An open question whose target cannot be labelled by business, date and time: not offered. */
  | "frontier_question_unlabelled"
  /** The bundle an open question was asked under is in neither KV nor PostgreSQL's copy: not offered. */
  | "frontier_bundle_missing"
  /** An open question's step (or its card) is not in the bundle it was asked under: not offered. */
  | "frontier_step_missing"
  /** A card's branch with no definition (K-01 means from none) or no branch of that label: that option is not offered. */
  | "frontier_option_unusable"
  /** An option naming an open question the frontier does not list (its source failed or left it out): not offered. */
  | "frontier_option_orphaned";

/** Everything a source reads: the request, the stored state as one read saw it, and the bundles read for this call. */
export interface FrontierInput {
  readonly request: BuildFrontierRequest;
  /** The business the call runs under (the request's caller.businessId). */
  readonly business: {
    readonly id: string;
    /** businesses.name (K-04 v1), the label of every choice about this business (arch 03 line 159). */
    readonly name: string;
    /** businesses.time_zone (K-04 v1): the zone a time is shown in when no visit gives one (CQ-05). */
    readonly zone: string;
  };
  readonly state: TurnState;
  /** Each open question's booking and its visit time, null when it could not be read. */
  readonly visits: ReadonlyMap<string, Time | null>;
  /** The flow of the context (frame.ts). */
  readonly flow: FlowLetter;
  /** The turn's pinned bundle. */
  readonly pinned: BundleView;
  /** Every bundle read for this call, by bundleKey(); null when it is in neither KV nor PostgreSQL's copy. */
  readonly bundles: ReadonlyMap<string, BundleView | null>;
  readonly log: FrontierLogger;
}

/** One source of choices (arch 03 lines 157 to 167). */
export interface FrontierSource {
  /** Its slot's name, a label (registry.ts). */
  readonly name: string;
  offer(input: FrontierInput): SourceOffer | Promise<SourceOffer>;
}

/** One slot of the frontier, in the order the frontier lists its choices; a slot whose task has not landed holds null. */
export interface SourceSlot {
  readonly name: string;
  readonly source: FrontierSource | null;
}

/** The key a bundle is cached under for one call. */
export function bundleKey(bundleId: BundleId): string {
  return `${bundleId.hash}/${String(bundleId.build)}`;
}
